package com.nextunlocks;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;

/** Quests from the bundled wiki data and diaries from the bundled unlocks, by wiki title. */
@Slf4j
class TaskRepository
{
	private static final String RESOURCE = "quests.json";

	private static class Data
	{
		List<RawQuest> quests;
	}

	private static class RawQuest
	{
		String name;
		String wiki;
		Map<String, Integer> skills;
		int questPoints;
		int combat;
		List<String> quests;
	}

	private Map<String, Task> byWiki = Collections.emptyMap();

	void load(Gson gson, Map<String, Map<Skill, Integer>> diaries) throws IOException
	{
		try (InputStream in = TaskRepository.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("missing " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				load(gson.fromJson(reader, Data.class), diaries);
			}
		}
	}

	private void load(Data data, Map<String, Map<Skill, Integer>> diaries)
	{
		Map<String, Task> tasks = new LinkedHashMap<>();
		for (RawQuest q : data.quests)
		{
			// a linked map keeps the data's order, highest level first
			Map<Skill, Integer> skills = new LinkedHashMap<>();
			if (q.skills != null)
			{
				q.skills.forEach((name, level) ->
				{
					try
					{
						skills.put(Skill.valueOf(name), level);
					}
					catch (IllegalArgumentException e)
					{
						log.debug("Skipping unknown skill {}", name);
					}
				});
			}
			List<String> quests = q.quests == null ? Collections.emptyList() : q.quests;
			tasks.put(q.wiki, new Task(q.name, q.wiki, false, skills, q.questPoints, q.combat, quests));
		}
		diaries.forEach((title, skills) ->
			tasks.put(title, new Task(title, title, true, skills, 0, 0, Collections.emptyList())));
		byWiki = tasks;
	}

	/** The quest or diary with this wiki title, or null. */
	Task get(String wiki)
	{
		return wiki == null ? null : byWiki.get(wiki);
	}

	/** The quest's name for a wiki title, or the title when it isn't known. */
	String name(String wiki)
	{
		Task task = get(wiki);
		return task == null ? wiki : task.getName();
	}

	/** The quest or diary with this name, or null. */
	Task byName(String name)
	{
		for (Task task : byWiki.values())
		{
			if (task.getName().equalsIgnoreCase(name))
			{
				return task;
			}
		}
		return null;
	}
}

package com.nextunlocks;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntConsumer;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.overlay.components.BackgroundComponent;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * Wraps the tooltip panel so it keeps its own background: RuneLite's tooltip overlay replaces the
 * background of any PanelComponent it is given with the default overlay color. Can draw an outline over the
 * panel's own border, and can be stretched taller than its content so boxes side by side line up.
 */
class TooltipBox implements LayoutableRenderableEntity
{
	private final PanelComponent panel;
	private final Color background;
	/** Null for none. */
	private final Color outline;
	private Point location = new Point();
	/** Panel size from the last render, before stretching; the panel lays out from its previous frame too. */
	@Getter
	private Dimension last;
	/** Height to stretch to when the content is shorter; 0 for the content's own height. */
	@Setter
	private int minHeight;

	/** Rewrite the xp numbers and progress for new xp. */
	private final List<IntConsumer> xpUpdates;

	TooltipBox(PanelComponent panel, Color background, Color outline, List<IntConsumer> xpUpdates)
	{
		this.panel = panel;
		this.background = background;
		this.outline = outline;
		this.xpUpdates = xpUpdates;
	}

	/** Update the xp shown without rebuilding, so the box keeps its size and place. */
	void updateXp(int xp)
	{
		xpUpdates.forEach(u -> u.accept(xp));
	}

	/** The icon tiles inside, where they were drawn last. */
	List<UnlockTileComponent> tiles()
	{
		List<UnlockTileComponent> tiles = new ArrayList<>();
		collect(panel, tiles);
		return tiles;
	}

	private static void collect(PanelComponent panel, List<UnlockTileComponent> tiles)
	{
		for (LayoutableRenderableEntity child : panel.getChildren())
		{
			if (child instanceof UnlockTileComponent)
			{
				tiles.add((UnlockTileComponent) child);
			}
			else if (child instanceof PanelComponent)
			{
				collect((PanelComponent) child, tiles);
			}
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// the background goes on first, sized to fit the stretched height, then the panel's content over it
		if (last != null && last.width > 0)
		{
			paintBackground(graphics, new Rectangle(location, new Dimension(last.width, Math.max(last.height, minHeight))));
		}
		panel.setBackgroundColor(null);
		Dimension size = panel.render(graphics);
		if (last == null && size.width > 0)
		{
			// first frame: nothing to size the background by yet, so it goes over the content's height
			last = size;
			return render(graphics);
		}
		last = size;
		Dimension stretched = new Dimension(size.width, Math.max(size.height, minHeight));
		if (outline != null && stretched.width > 0 && stretched.height > 0)
		{
			Color color = graphics.getColor();
			graphics.setColor(outline);
			graphics.drawRect(location.x, location.y, stretched.width - 1, stretched.height - 1);
			graphics.setColor(color);
		}
		return stretched;
	}

	private void paintBackground(Graphics2D graphics, Rectangle bounds)
	{
		BackgroundComponent back = new BackgroundComponent();
		back.setRectangle(bounds);
		back.setBackgroundColor(background);
		back.render(graphics);
	}

	@Override
	public Rectangle getBounds()
	{
		Rectangle bounds = panel.getBounds();
		return new Rectangle(bounds.x, bounds.y, bounds.width, Math.max(bounds.height, minHeight));
	}

	@Override
	public void setPreferredLocation(Point position)
	{
		location = position;
		panel.setPreferredLocation(position);
	}

	@Override
	public void setPreferredSize(Dimension dimension)
	{
		panel.setPreferredSize(dimension);
	}
}

